// Set for O(1) lookup per length
const VALID_BY_LENGTH = {};
for (const [len, words] of Object.entries(WORDS_BY_LENGTH)) {
  VALID_BY_LENGTH[len] = new Set(words);
}

function getRandomWordOfLength(len) {
  const words = WORDS_BY_LENGTH[len];
  if (!words || words.length === 0) throw new Error('No words for length: ' + len);
  return words[Math.floor(Math.random() * words.length)];
}

function isValidWord(word) {
  const upper = word.toUpperCase();
  const set = VALID_BY_LENGTH[upper.length];
  return !!(set && set.has(upper));
}

module.exports = { WORDS_BY_LENGTH, VALID_BY_LENGTH, getRandomWordOfLength, isValidWord };
